// Sub-Workflow, Code-Node "Mail vorbereiten"  –  Mode: "Run Once for Each Item", JavaScript
// Bekommt Items aus ALLEN Enden des Hauptworkflows (Angebot, Rueckfrage, Aussortiert,
// Kein Katalogtreffer, Manuelle Pruefung), vereinheitlicht die Felder fuer Supabase
// und baut Betreff + Text der Mail passend zum Status.

const d = $json;
const status = d.status || 'Manuelle Pruefung';
const firma = d.firma || 'Unbekannt';

const liste = v => (Array.isArray(v) ? v : []);
const pgArray = arr => '{' + liste(arr).map(v => `"${String(v).replace(/"/g, '')}"`).join(',') + '}';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const br = s => esc(s).replace(/\n/g, '<br>');

const fehlend = liste(d.fehlende_angaben);
const valFehler = liste(d.validierungsfehler);

// Laufzeit: aus dem Angebotszweig uebernehmen, sonst hier berechnen
const laufzeit = d.laufzeit_s ?? (d.startzeit
  ? Math.round((Date.now() - new Date(d.startzeit).getTime()) / 100) / 10
  : null);

const kopf =
  `<p><b>Firma:</b> ${esc(firma)}<br>` +
  `<b>Ansprechpartner:</b> ${esc(d.ansprechpartner || '–')}<br>` +
  `<b>E-Mail:</b> ${esc(d.email || '–')}<br>` +
  `<b>Status:</b> ${esc(status)}</p>`;
const anfrage = `<p><b>Originalanfrage:</b><br>${br(d.rohtext)}</p>`;

let betreff = null;
let inhalt = null;
let senden = true;
let text = d.angebotstext || null;   // Angebots- bzw. Rueckfragetext fuer Supabase

switch (status) {
  case 'Angebot erstellt':
    betreff = `[Neues Angebot] ${firma} – ${Number(d.angebotssumme_eur || 0).toLocaleString('de-DE')} EUR`;
    inhalt = kopf + `<p>${br(text)}</p>`;
    break;

  case 'Rueckfrage':
    text =
      'Sehr geehrte Damen und Herren,\n\n' +
      'vielen Dank für Ihre Anfrage. Damit wir Ihnen ein Angebot erstellen können, ' +
      `benötigen wir noch folgende Angaben: ${fehlend.join(', ')}.\n\n` +
      'Mit freundlichen Grüßen\nIhr Vertriebsteam';
    betreff = `[Rückfrage nötig] ${firma} – fehlt: ${fehlend.join(', ')}`;
    inhalt = kopf + `<p><b>Vorschlag für die Rückfrage an den Kunden:</b><br>${br(text)}</p>` + anfrage;
    break;

  case 'Kein Katalogtreffer':
    betreff = `[Kein Katalogtreffer] ${firma} – ${d.produktbeschreibung || 'unbekanntes Produkt'}`;
    inhalt = kopf + '<p>Für dieses Produkt gibt es keine Leistung im Katalog. Bitte fachlich prüfen.</p>' + anfrage;
    break;

  case 'Aussortiert':
    senden = false;   // Spam & Co.: nur speichern, keine Mail
    break;

  default: // 'Manuelle Pruefung' und alles Unerwartete
    betreff = `[Manuelle Prüfung] ${firma}`;
    inhalt = kopf +
      `<p><b>Grund:</b> ${esc(valFehler.join('; ') || 'unbekannt')}</p>` +
      anfrage +
      `<p><b>LLM-Rohantwort:</b><br>${br(d.llm_rohantwort)}</p>`;
}

return {
  json: {
    // Felder fuer die Tabelle "anfragen"
    firma: firma,
    ansprechpartner: d.ansprechpartner || null,
    email: d.email || null,
    produktkategorie: d.produktkategorie || null,
    zielmaerkte_pg: pgArray(d.zielmaerkte),
    fehlende_angaben_pg: pgArray(fehlend),
    status: status,
    angebotssumme_eur: d.angebotssumme_eur ?? null,
    token_kosten_usd: d.kosten_usd ?? null,
    laufzeit_s: laufzeit,
    rohtext: d.rohtext || null,
    angebotstext: text,
    // Steuerung der Mail
    mail_senden: senden,
    mail_betreff: betreff,
    mail_html: inhalt,
  },
};
